cells={(r,c) for r,row in enumerate([[0,8,8,0,8,8,0],[8,8,8,8,8,8,0],[0,8,8,0,8,0,0],[0,0,8,8,8,0,0]]) for c,v in enumerate(row) if v}
from itertools import product
motifs=[]
for r in range(3):
 for c in range(6):
  box={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  occ=box&cells
  if len(occ) in (3,4): motifs.append((occ,(r,c),len(occ),box-occ))
solutions=[]
def search(rem, chosen):
 if not rem:
  solutions.append(chosen); return
 x=next(iter(rem))
 for occ,loc,n,missing in motifs:
  if x in occ and occ<=rem:
   search(rem-occ,chosen+[(occ,loc,n,missing)])
search(cells,[])
len(solutions),[[(x[1],x[2],x[3]) for x in s] for s in solutions[:20]]
